			public static void drawText(string text, float x, float y, float scale, int r, int g, int b)
			{
				Function.Call(Hash.BEGIN_TEXT_COMMAND_DISPLAY_TEXT, "STRING");
				Function.Call(Hash.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME, text);
				Function.Call(Hash.SET_TEXT_COLOUR, r, g, b, 255);
				Function.Call(Hash.SET_TEXT_SCALE, 0f, scale);
				Function.Call(Hash.END_TEXT_COMMAND_DISPLAY_TEXT, x, y, 0.1);
			}

			private static void drawSprite2(string textureDict, string textureName, float screenX, float screenY, float width, float height, int r, int g, int b, int alpha)
			{
				Function.Call(Hash.REQUEST_STREAMED_TEXTURE_DICT, textureDict, 0);
				if (Function.Call<bool>(Hash.HAS_STREAMED_TEXTURE_DICT_LOADED, textureDict))
				{
					Function.Call(Hash.DRAW_SPRITE, textureDict, textureName, screenX, screenY, width, height, 0, r, g, b, alpha, 0);
				}
			}

			public void OnTick(object sender, EventArgs e)
			{
				if (!SetupCasinoPeds)
				{
					SetupCasinoPeds = true;
					foreach (Vector4 item in CasinoPedSpawn)
					{
						Script.Wait(1);
						Random random = new Random();
						Vector3 spawn = new Vector3(item.X, item.Y, item.Z);
						CasinoPeds.Add(new CasinoPedV2(CasinoPedModels[random.Next(0, CasinoPedModels.Count)], spawn, item.H));
					}
				}
				if (!MissionOn || HeistStage != 2 || MissionStage != 5)
				{
					return;
				}
				int missionStage = MissionStage;
				int num2 = 5;
				if (Game.GameTime < NextPedCheck)
				{
					return;
				}
				NextPedCheck = Game.GameTime + 3500;
				int num = 0;
				if (!SetupCasinoPeds)
				{
					return;
				}
				foreach (CasinoPedV2 casinoPed in CasinoPeds)
				{
					Vector3 vector = new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z);
					Vector2 vector2 = World3DToScreen2d(vector);
					if (casinoPed.CreatedPed)
					{
						if (casinoPed.Ped != null && !casinoPed.Ped.Exists())
						{
							casinoPed.CreatedPed = false;
						}
						if (casinoPed.Ped == null)
						{
							casinoPed.CreatedPed = false;
						}
						if (casinoPed.Ped != null)
						{
							if (Game.GameTime >= casinoPed.AnimCheck)
							{
								if (!Function.Call<bool>(Hash.IS_ENTITY_PLAYING_ANIM, casinoPed.AnimDict, casinoPed.AnimDict, 3))
								{
									casinoPed.Ped.Task.PlayAnimation(casinoPed.AnimDict, casinoPed.AnimName, 1f, -1, AnimationFlags.Loop);
								}
								casinoPed.AnimCheck = Game.GameTime + 2500;
							}
							if (casinoPed.AnimDict.Contains("withdrink") && casinoPed.AnimDict.Contains("01a"))
							{
								if (casinoPed.Prop == null)
								{
									casinoPed.Prop = World.CreateProp(RequestModel("prop_cs_beer_bot_01"), new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z - 1f), false, false);
									Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, casinoPed.Prop, casinoPed.Ped, casinoPed.Ped.Bones[Bone.PHLeftHand].Index, 0f, 0f, 0.08f, 0f, 0f, 0f, true, true, false, true, 1, true);
								}
								if (casinoPed.Prop != null && !casinoPed.Prop.Exists())
								{
									casinoPed.Prop = World.CreateProp(RequestModel("prop_cs_beer_bot_01"), new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z - 1f), false, false);
									Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, casinoPed.Prop, casinoPed.Ped, casinoPed.Ped.Bones[Bone.PHLeftHand].Index, 0f, 0f, 0.08f, 0f, 0f, 0f, true, true, false, true, 1, true);
								}
							}
							if (casinoPed.AnimDict.Contains("withdrink") && !casinoPed.AnimDict.Contains("01a"))
							{
								if (casinoPed.Prop == null)
								{
									casinoPed.Prop = World.CreateProp(RequestModel("prop_cs_beer_bot_01"), new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z - 1f), false, false);
									Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, casinoPed.Prop, casinoPed.Ped, casinoPed.Ped.Bones[Bone.PHRightHand].Index, 0f, 0f, 0.08f, 0f, 0f, 0f, true, true, false, true, 1, true);
								}
								if (casinoPed.Prop != null && !casinoPed.Prop.Exists())
								{
									casinoPed.Prop = World.CreateProp(RequestModel("prop_cs_beer_bot_01"), new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z - 1f), false, false);
									Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, casinoPed.Prop, casinoPed.Ped, casinoPed.Ped.Bones[Bone.PHRightHand].Index, 0f, 0f, 0.08f, 0f, 0f, 0f, true, true, false, true, 1, true);
								}
							}
							if (casinoPed.AnimDict.Contains("cellphone"))
							{
								if (casinoPed.Prop == null)
								{
									casinoPed.Prop = World.CreateProp(RequestModel("prop_amb_phone"), new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z - 1f), false, false);
									Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, casinoPed.Prop, casinoPed.Ped, casinoPed.Ped.Bones[Bone.PHRightHand].Index, 0.005f, 0.015f, -0.035f, 0f, 0f, 0f, true, true, false, true, 1, true);
								}
								if (casinoPed.Prop != null && !casinoPed.Prop.Exists())
								{
									casinoPed.Prop = World.CreateProp(RequestModel("prop_amb_phone"), new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z - 1f), false, false);
									Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, casinoPed.Prop, casinoPed.Ped, casinoPed.Ped.Bones[Bone.PHRightHand].Index, 0.005f, 0.015f, -0.035f, 0f, 0f, 0f, true, true, false, true, 1, true);
								}
							}
							Function.Call(Hash.SET_RAGDOLL_BLOCKING_FLAGS, casinoPed.Ped, 13);
							Function.Call(Hash.SET_RAGDOLL_BLOCKING_FLAGS, casinoPed.Ped, 14);
							Function.Call(Hash.SET_RAGDOLL_BLOCKING_FLAGS, casinoPed.Ped, 4);
							Function.Call(Hash.SET_PED_FLEE_ATTRIBUTES, casinoPed.Ped, 0, 0);
							Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, casinoPed.Ped, 17, 1);
							Function.Call(Hash.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, casinoPed.Ped, 1);
							Function.Call(Hash.SET_PED_FLEE_ATTRIBUTES, casinoPed.Ped, 0, 0);
							Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, casinoPed.Ped, 17, 1);
						}
					}
					if (GetDistance_VDIST2(Game.Player.Character.Position, vector, "<", 40f))
					{
						if (casinoPed.CreatedPed)
						{
							casinoPed.TimeSinceLastOnScreen = 0;
						}
						if (!casinoPed.CreatedPed)
						{
							casinoPed.Ped = World.CreatePed(RequestModel(casinoPed.Model), new Vector3(casinoPed.Position.X, casinoPed.Position.Y, casinoPed.Position.Z - 1f), casinoPed.heading);
							if (casinoPed.Ped != null)
							{
								casinoPed.Ped.IsPositionFrozen = true;
								casinoPed.Ped.BlockPermanentEvents = true;
								casinoPed.Ped.AlwaysKeepTask = true;
								casinoPed.Ped.Task.PlayAnimation(casinoPed.AnimDict, casinoPed.AnimName, 1f, -1, AnimationFlags.Loop);
								Function.Call(Hash.SET_RAGDOLL_BLOCKING_FLAGS, casinoPed.Ped, 13);
								Function.Call(Hash.SET_RAGDOLL_BLOCKING_FLAGS, casinoPed.Ped, 14);
								Function.Call(Hash.SET_RAGDOLL_BLOCKING_FLAGS, casinoPed.Ped, 4);
								Function.Call(Hash.SET_RAGDOLL_BLOCKING_FLAGS, casinoPed.Ped, 15);
								casinoPed.Ped.RelationshipGroup = 1;
								casinoPed.Ped.AlwaysKeepTask = true;
								LoadCasinoPedOutfit(casinoPed.Ped, casinoPed.Outfit);
							}
							casinoPed.CreatedPed = true;
						}
						bool createdPed = casinoPed.CreatedPed;
						num++;
					}
					else
					{
						if (!casinoPed.CreatedPed)
						{
							continue;
						}
						casinoPed.CreatedPed = false;
						if (casinoPed.Ped != null)
						{
							if (casinoPed.Prop != null)
							{
								casinoPed.Prop.Delete();
							}
							casinoPed.Ped.Delete();
						}
					}
				}
			}
		}

