				LGateModel = LeftGateModel;
				IsChainGate = false;
				GateLocked = true;
			}

			public void UnlockGate()
			{
				if (IsChainGate)
				{
					Prop closestProp = GetClosestProp(LGatePosition, LGateModel);
					Prop closestProp2 = GetClosestProp(RGatePosition, RGateModel);
					bool flag = closestProp != null;
					bool flag2 = closestProp2 != null;
					if (GateLocked)
					{
						if (closestProp != null)
						{
							closestProp.IsPositionFrozen = true;
						}
						if (closestProp2 != null)
						{
							closestProp2.IsPositionFrozen = true;
						}
						if (GotBoltCutters || Retrieved_CuttingTorch)
						{
							if (!CreatedGate && GetDistance(Game.Player.Character.Position, LockPosition) < 15f)
							{
								CreatedGate = true;
								if (BoltCutterProp != null)
								{
									BoltCutterProp.Delete();
								}
								if (Chain != null)
								{
									Chain.Delete();
								}
								LeftGate = closestProp;
								RightGate = closestProp2;
								Chain = World.CreateProp(RequestModel("h4_prop_h4_chain_lock_01a"), LockPosition, new Vector3(0f, 0f, Lockheading), false, false);
							}
							if (CreatedGate && !DisableDeleteBoltCutters && GetDistance(Game.Player.Character.Position, LockPosition) > 15f)
							{
								CreatedGate = false;
								if (CutGateBagProp != null)
