								{
									if (CutGateType == 1)
									{
										if (CutGateStage == 1 && Function.Call<int>(Hash.GET_SYNCHRONIZED_SCENE_PHASE, Scene1) >= 1054353216)
										{
											Function.Call(Hash.REQUEST_NAMED_PTFX_ASSET, "scr_ornate_heist");
