										}
									}
									if (Function.Call<int>(Hash.GET_SYNCHRONIZED_SCENE_PHASE, Scene1) >= 1065353216)
									{
										Function.Call(Hash.SET_SYNCHRONIZED_SCENE_PHASE, Scene1, 0.0);
										if (CutGateBagProp != null)
										{
											if (Game.Player.Name.ToUpper().Equals(DebugName))
