										}
										if (closestProp2 != null)
										{
											closestProp2.IsPositionFrozen = false;
										}
										Chain.IsPositionFrozen = false;
										Game.Player.Character.Task.ClearAll();
										GateLocked = false;
										CreatedGate = false;
										DisableDeleteBoltCutters = false;
									}
								}
							}
						}
						if (!GotBoltCutters && !Retrieved_CuttingTorch && GetDistance(Game.Player.Character.Position, LockPosition) < 2f && !CuttingGate)
						{
							DisplayHelpTextThisFrame("You Need Bolt Cutters/Cutting Torch To Open this Gate");
						}
					}
					else if (GetDistance(Game.Player.Character.Position, LockPosition) < 15f)
					{
						if (closestProp != null)
						{
							closestProp.IsPositionFrozen = false;
						}
						if (closestProp2 != null)
						{
							closestProp2.IsPositionFrozen = false;
						}
					}
					return;
				}
				Prop closestProp3 = GetClosestProp(LGatePosition, LGateModel);
				if (GateLocked)
				{
					if (GotMasterKey)
					{
						if (!CreatedGate && GetDistance(Game.Player.Character.Position, LGatePosition) < 15f)
						{
							CreatedGate = true;
							if (BoltCutterProp != null)
							{
								BoltCutterProp.Delete();
							}
							if (Chain != null)
							{
								Chain.Delete();
							}
						}
						if (CreatedGate && GetDistance(Game.Player.Character.Position, LGatePosition) > 15f && !GateLocked)
						{
							CreatedGate = false;
							if (BoltCutterProp != null)
							{
								BoltCutterProp.Delete();
							}
							if (Chain != null)
							{
								Chain.Delete();
							}
						}
						if (GetDistance(Game.Player.Character.Position, LGatePosition) < 10f)
						{
							if (!CuttingGate && GateLocked && closestProp3 != null)
							{
								closestProp3.IsPositionFrozen = true;
								if (GetDistance(Game.Player.Character.Position, closestProp3.GetOffsetPosition(new Vector3(-0.75f, 1.5f, 0f))) < 1.25f)
								{
