										{
											MoneyProp.Delete();
											MoneyProp.MarkAsNoLongerNeeded();
											MoneyProp = null;
										}
										MoneyProp = World.CreateProp(RequestModel("h4_prop_h4_key_desk_01"), Game.Player.Character.Position, default(Vector3), false, false);
										MoneyProp.IsPositionFrozen = true;
										MoneyProp.IsCollisionEnabled = false;
										MoneyProp.IsInvincible = true;
										Vector3 rotation3 = closestProp3.Rotation;
										Vector3 offsetPosition = closestProp3.GetOffsetPosition(new Vector3(-2f, 0f, 0f));
										Scene1 = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE, offsetPosition.X, offsetPosition.Y, offsetPosition.Z, 0.0, 0.0, rotation3.Z - 180f, 2);
