								{
									BoltCutterProp.Delete();
								}
								if (Chain != null)
								{
									Chain.Delete();
								}
								if (closestProp3 != null)
								{
									closestProp3.IsPositionFrozen = false;
								}
								if (RobberA != null)
								{
