		public static void DisplayHelpTextThisFrame(string helpText, int Shape)
		{
			Function.Call(Hash.BEGIN_TEXT_COMMAND_DISPLAY_HELP, "CELL_EMAIL_BCON");
			int num = 99;
			for (int i = 0; i < helpText.Length; i += num)
			{
				Function.Call(Hash.ADD_TEXT_COMPONENT_SUBSTRING_PLAYER_NAME, helpText.Substring(i, Math.Min(num, helpText.Length - i)));
			}
			Function.Call(Hash.END_TEXT_COMMAND_DISPLAY_HELP, 0, 0, 1, Shape);
		}

		public void Setup_gmm_cartelguards_01(Ped ped)
		{
			Random random = new Random();
			int num = random.Next(0, 1000);
			if (num < 100)
			{
				int num2 = random.Next(0, 3);
				Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 0, num2, random.Next(0, 2), 1);
				Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 2, random.Next(0, 1), random.Next(0, 2), 1);
				int num3 = random.Next(0, 2);
				if (num3 == 2)
				{
					if (num2 == 3)
					{
						Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 4, num3, random.Next(0, 2), 1);
					}
					else
					{
						Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 4, num3, random.Next(3, 5), 1);
					}
				}
				else
				{
					Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 4, num3, 0, 1);
				}
				int num4 = 0;
				num4 = ((num2 == 4) ? 1 : 0);
				Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 5, num4, 0, 1);
				Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 6, random.Next(0, 2), random.Next(0, 2), 1);
				int num5 = random.Next(0, 100);
				if (num5 <= 50)
				{
					Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 9, 0, random.Next(0, 3), 1);
				}
				if (num5 > 50)
				{
					Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 9, 1, 0, 1);
				}
				Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 10, random.Next(0, 2), random.Next(0, 2), 1);
				Function.Call(Hash.SET_PED_COMPONENT_VARIATION, ped, 11, random.Next(0, 3), random.Next(0, 2), 1);
				Script.Wait(1);
			}
			if (num >= 100)
			{
				int num6 = 200;
			}
		}

