		public CayoPericoHeist()
		{
			Assembly executingAssembly = Assembly.GetExecutingAssembly();
			string fullName = executingAssembly.FullName;
			if (fullName.Contains("SinglePlayerHeists"))
			{
				Is_Standalone_CayoPericoInSP_Mod = false;
			}
			if (Is_Standalone_CayoPericoInSP_Mod)
			{
				CanInitializeYTD = true;
			}
			KosatkaPos = new Vector3(1564.171f, 383.7477f, -50.5f);
			base.Tick += MainUpdate;
			base.Aborted += OnShutdown;
			Setup();
		}

