		public void Setup()
		{
			CreateBanner();
			modLemonUIObjectPool = new ObjectPool();
			mainMenu = new NativeMenu(" ", "Select an Option");
			Heists = mainMenu;
			modLemonUIObjectPool.Add(mainMenu);
			GLemonUIMenusNativeMenus.Add(Heists);
			GLemonUIMenusNativeMenus.Add(mainMenu);
			Loadout_modLemonUIObjectPool = new ObjectPool();
			Loadout_mainMenu = new NativeMenu("", "Select an Option");
			Loadout_modLemonUIObjectPool.Add(Loadout_mainMenu);
			GLemonUIMenusNativeMenus.Add(Loadout_mainMenu);
			List<string> list = new List<string>();
			list.Add("Aggressor");
			list.Add("Conspirator");
			list.Add("Crack Shot");
			list.Add("Saboteur");
			list.Add("Marksman");
			object[] objs = list.ToArray();
			NativeListItem<dynamic> LoadOutList = new NativeListItem<object>("Loudout:", objs);
			Loadout_mainMenu.Add(LoadOutList);
			LoadOutList.Description = "Selected Loadout For Cayo Perico Heist:\n~Aggressor~\nAssault Shotgun\nMachine Pistol\nMachete\n5 Grenades";
			LoadOutList.ItemChanged += delegate
			{
				if (LoadOutList.SelectedIndex == 0)
				{
					LoadOutList.Description = "Selected Loadout For Cayo Perico Heist:\n~Aggressor~\nAssault Shotgun\nMachine Pistol\nMachete\n5 Grenades";
				}
				if (LoadOutList.SelectedIndex == 1)
				{
					LoadOutList.Description = "Selected Loadout For Cayo Perico Heist:\n~Conspirator~\nMilitary Rifle\nPistol .50\nKnuckle Dusters\n5 Sticky Bombs";
				}
				if (LoadOutList.SelectedIndex == 2)
				{
					LoadOutList.Description = "Selected Loadout For Cayo Perico Heist:\n~Crack Shot~\nSniper Rifle\nAP Pistol\nKnife\n5 Molotov Cocktails";
				}
				if (LoadOutList.SelectedIndex == 3)
				{
					LoadOutList.Description = "Selected Loadout For Cayo Perico Heist:\n~Saboteur~\nSMG Mk II w/ Hollow Point rounds\nSNS Pistol Mk II w/ Hollow Point rounds\nKnife\n5 Pipe Bomb";
				}
				if (LoadOutList.SelectedIndex == 4)
				{
					LoadOutList.Description = "Selected Loadout For Cayo Perico Heist:\n~Marksman~\nAssault Rifle Mk II w/ Full Metal Jacket rounds\nPistol Mk II w/  Full Metal Jacket rounds\nMachete\n5 Pipe Bomb";
				}
			};
			NativeCheckboxItem Silencer = new NativeCheckboxItem("Equip Suppressors ");
			Loadout_mainMenu.Add(Silencer);
			Silencer.Checked = true;
			Silencer.Description = "Toggles Whether Player has suppressors on their guns during Finale.";
			Silencer.CheckboxChanged += delegate
			{
				UseSuppressors = Silencer.Checked;
				Config.SetValue("CAYOPERICOHEIST", "Player_Use_Suppressor_In_Finale", UseSuppressors);
				Config.Save();
			};
			NativeItem nativeItem = new NativeItem("Set Loadout", "", "$5,000");
			Loadout_mainMenu.Add(nativeItem);
			nativeItem.Description = "Sets the Weapons to be used during Finale, Note: Only weapons in Player's Choosen Loadout will be usuable during finale, all others will be locked.";
			nativeItem.Activated += delegate
			{
				Current_Weapon_Loadout = LoadOutList.SelectedIndex;
				Config.SetValue("CAYOPERICOHEIST", "Player_Finale_Selected_Loadout", Current_Weapon_Loadout);
				Config.Save();
				ChoosenWeaponLoadOut = true;
			};
			for (int i = 0; i < GLemonUIMenusNativeMenus.Count; i++)
			{
				NativeMenu banner = GLemonUIMenusNativeMenus[i];
				SetBanner(banner);
			}
			if (!Is_Standalone_CayoPericoInSP_Mod)
			{
				Heist_Return_Location = "Arcade";
				KosatkaScript.GetMainDirectory();
				LoadIniFile(KosatkaScript.MainDirectory + "Main.ini");
			}
			else
			{
				Heist_Return_Location = "Kosatka";
				KosatkaScript.GetMainDirectory();
				LoadIniFile(KosatkaScript.MainDirectory + "Heist.ini");
			}
			Prop[] nearbyProps = World.GetNearbyProps(Game.Player.Character.Position, 1f);
			if (GetDistance(Game.Player.Character.Position, new Vector3(312.0821f, -283.3166f, 54f)) < 3f)
			{
				Prop[] nearbyProps2 = World.GetNearbyProps(new Vector3(312.0821f, -283.3166f, 54f), 1f);
				if (nearbyProps2.Length != 0)
				{
					Prop[] array = nearbyProps2;
					foreach (Prop prop in array)
					{
						if (prop != null && prop.Rotation.Z >= -179f)
						{
							float z = prop.Rotation.Z;
							prop.Rotation = new Vector3(0f, 0f, -110f);
						}
					}
				}
			}
			modLemonUIObjectPool3 = new ObjectPool();
			mainMenu3 = new NativeMenu("Drinks", "Select an Option");
			GLemonUIMenusNativeMenus.Add(mainMenu3);
			DrinksMenu = new NativeMenu("Cayo Perico", "Drinks");
			mainMenu3.AddSubMenu(DrinksMenu);
			modLemonUIObjectPool3.Add(DrinksMenu);
			GLemonUIMenusNativeMenus.Add(DrinksMenu);
			Drinks();
			for (int k = 0; k < GLemonUIMenusNativeMenus.Count; k++)
			{
				NativeMenu banner2 = GLemonUIMenusNativeMenus[k];
				SetBanner(banner2);
			}
			if (!Is_Standalone_CayoPericoInSP_Mod)
			{
				Heist_Return_Location = "Arcade";
				KosatkaScript.GetMainDirectory();
				LoadIniFile(KosatkaScript.MainDirectory + "Main.ini");
			}
			else
			{
				Heist_Return_Location = "Kosatka";
				KosatkaScript.GetMainDirectory();
				LoadIniFile(KosatkaScript.MainDirectory + "Heist.ini");
			}
		}

