					Prop prop8 = World.CreateProp(RequestModel("ba_prop_battle_champ_closed_03"), Game.Player.Character.GetOffsetPosition(new Vector3(5f, 0f, -1f)), false, false);
					prop8.IsPositionFrozen = true;
