		public static void LoadIniFile(string iniName)
		{
			Config = ScriptSettings.Load(iniName);
			HeistStage = Config.GetValue("CayoPericoHeist", "HeistStage", HeistStage);
			PilotCut = Config.GetValue("CayoPericoHeist", "PILOTCUT", PilotCut);
			VehicleEnteranceMethod = Config.GetValue("CayoPericoHeist", "VEHICLETOUSE", VehicleEnteranceMethod);
			UsedCuttingPowderInSetup = Config.GetValue("CayoPericoHeist", "UsedCuttingPowderInSetup", UsedCuttingPowderInSetup);
			MainTargetID = Config.GetValue("CayoPericoHeist", "CurrentMainTargetID", MainTargetID);
			if (MainTargetID >= 0 && MainTargetID <= 4)
			{
				CurrentMainTargetID = (MainTargets)MainTargetID;
			}
			else
			{
				MainTargetID = 0;
				CurrentMainTargetID = MainTargets.MadrazoFiles;
			}
			SetMainTargetString(MainTargetID);
			FirstTimePlayed = Config.GetValue("CayoPericoHeist", "FirstTimePlayed", FirstTimePlayed);
			Current_Weapon_Loadout = Config.GetValue("CAYOPERICOHEIST", "Player_Finale_Selected_Loadout", Current_Weapon_Loadout);
			UseSuppressors = Config.GetValue("CAYOPERICOHEIST", "Player_Use_Suppressor_In_Finale", UseSuppressors);
			MainTarget_Value_Madrazo_Files = Config.GetValue("CayoPericoHeist-Main_Targets", "Madrazo_Files", MainTarget_Value_Madrazo_Files);
			MainTarget_Value_Sinsimito_Tequila = Config.GetValue("CayoPericoHeist-Main_Targets", "Sinsimito_Tequila ", MainTarget_Value_Sinsimito_Tequila);
			MainTarget_Value_Ruby_Necklace = Config.GetValue("CayoPericoHeist-Main_Targets", "Ruby_Necklace", MainTarget_Value_Ruby_Necklace);
			MainTarget_Value_Bearer_Bonds = Config.GetValue("CayoPericoHeist-Main_Targets", "Bearer_Bonds", MainTarget_Value_Bearer_Bonds);
			MainTarget_Value_Pink_Diamond = Config.GetValue("CayoPericoHeist-Main_Targets", "Pink_Diamond", MainTarget_Value_Pink_Diamond);
			MainTarget_Value_Panther_Statue = Config.GetValue("CayoPericoHeist-Main_Targets", "Panther_Statue", MainTarget_Value_Panther_Statue);
			GetSetupVariable();
			try
			{
				if (Is_Standalone_CayoPericoInSP_Mod)
				{
					HeistMinPay = Config.GetValue("Pay", "MINPay", (int)HeistMinPay);
					HeistMaxPay = Config.GetValue("Pay", "MAXPay", (int)HeistMaxPay);
				}
				else
				{
					HeistMinPay = Config.GetValue("CayoPericoHeist", "MINPay", (int)HeistMinPay);
					HeistMaxPay = Config.GetValue("CayoPericoHeist", "MAXPay", (int)HeistMaxPay);
				}
			}
			catch (Exception)
			{
				Notification.Show("~r~Error~w~: Cayo Perico Heist/ Cannot Get Heist Pay, Please Reinstall Mod");
			}
		}

		public static float CalculateMaxPay(int min, int max)
		{
			float result = 0f;
			Random random = new Random();
			if (min < max)
			{
				result = random.Next(min, max);
			}
			if (min > max)
			{
				result = random.Next(max, min);
			}
			return result;
		}

		public float increaseCurrentPay(int min, int max)
		{
			float num = 0f;
			Random random = new Random();
			if (min < max)
			{
				num = random.Next(min, max);
				CurrentPay += (int)num;
			}
			if (min > max)
			{
				num = random.Next(max, min);
				CurrentPay += (int)num;
			}
			return num;
		}

		public static string LoadDict(string dict)
		{
			while (!Function.Call<bool>(Hash.HAS_ANIM_DICT_LOADED, dict))
			{
				Function.Call(Hash.REQUEST_ANIM_DICT, dict);
				Script.Yield();
			}
			return dict;
		}

