		public void GlobalAttackPlayer(Ped Ped)
		{
			if (GetDistance(Game.Player.Character.Position, new Vector3(5017.216f, -5737.826f, 17.66f)) > 100f)
			{
				Ped[] nearbyPeds = World.GetNearbyPeds(Ped.Position, 15f);
				if (nearbyPeds.Length != 0)
				{
					Ped[] array = nearbyPeds;
					foreach (Ped ped in array)
					{
						if (ped.Model == RequestModel("g_m_m_cartelguards_01") && !ped.IsInCombat)
						{
							ped.Task.FightAgainst(Game.Player.Character);
						}
					}
				}
			}
			if (!(GetDistance(Game.Player.Character.Position, new Vector3(5017.216f, -5737.826f, 17.66f)) < 100f))
			{
				return;
			}
			Ped[] nearbyPeds2 = World.GetNearbyPeds(Ped.Position, 25f);
			if (nearbyPeds2.Length == 0)
			{
				return;
			}
			Ped[] array2 = nearbyPeds2;
			foreach (Ped ped2 in array2)
			{
				if (ped2.Model == RequestModel("g_m_m_cartelguards_01") && !ped2.IsInCombat)
				{
					ped2.Task.FightAgainst(Game.Player.Character);
				}
			}
		}

