		public Vector3 ToVector3(string Name)
		{
			Vector3 result = new Vector3(0f, 0f, 0f);
			string[] separator = new string[3] { "X:", "Y:", "Z:" };
			string[] array = Name.Split(separator, StringSplitOptions.RemoveEmptyEntries);
			try
			{
				result = new Vector3(float.Parse(array[0], NumberStyles.Any), float.Parse(array[1], NumberStyles.Any), float.Parse(array[2], NumberStyles.Any));
				return result;
			}
			catch (Exception)
			{
				return result;
			}
		}

