			SmartAISettings_Guards.ShowCone = true;
			SmartAISettings_Secondary_AirfieldGuards = SmartGuards.CreateSettingsForGroup(SmartGuards.EnemyGroup.Cayo_Perico_Cartel);
			SmartAISettings_Secondary_PartyGuards = SmartGuards.CreateSettingsForGroup(SmartGuards.EnemyGroup.Cayo_Perico_Cartel);
			SmartAISettings_Secondary_NorthDocksGuards = SmartGuards.CreateSettingsForGroup(SmartGuards.EnemyGroup.Cayo_Perico_Cartel);
