					northDocksGuard.AIPed.Delete();
				}
				if (northDocksGuard.AiProp != null)
				{
					northDocksGuard.AiProp.Delete();
				}
			}
			foreach (SmartGuards.SmartAiV2 partyGuard in PartyGuards)
