				}
			}
			foreach (SmartGuards.SmartAiV2 southDockGuard in SouthDockGuards)
			{
				southDockGuard.SpawnGroupArea = southDockGuard.OriginalPosition;
				southDockGuard.GroupActive = false;
				if (southDockGuard.LastVehicle != null)
				{
					southDockGuard.LastVehicle.Delete();
				}
				if (southDockGuard.AIPed != null)
				{
					southDockGuard.AIPed.Delete();
				}
				if (southDockGuard.AiProp != null)
				{
					southDockGuard.AiProp.Delete();
				}
			}
			foreach (SmartGuards.SmartAiV2 fieldGuard in FieldGuards)
			{
				fieldGuard.SpawnGroupArea = fieldGuard.OriginalPosition;
				fieldGuard.GroupActive = false;
				if (fieldGuard.LastVehicle != null)
				{
					fieldGuard.LastVehicle.Delete();
				}
				if (fieldGuard.AIPed != null)
				{
					fieldGuard.AIPed.Delete();
				}
				if (fieldGuard.AiProp != null)
				{
					fieldGuard.AiProp.Delete();
				}
			}
			foreach (SmartGuards.SmartAiV2 compoundGuard in CompoundGuards)
			{
				compoundGuard.SpawnGroupArea = compoundGuard.OriginalPosition;
				compoundGuard.GroupActive = false;
				if (compoundGuard.LastVehicle != null)
				{
					compoundGuard.LastVehicle.Delete();
				}
				if (compoundGuard.AIPed != null)
				{
					compoundGuard.AIPed.Delete();
				}
				if (compoundGuard.AiProp != null)
				{
					compoundGuard.AiProp.Delete();
				}
			}
			AirfieldGuards.Clear();
			NorthDocksGuards.Clear();
			PartyGuards.Clear();
			CheckpointGuards.Clear();
			SouthDockGuards.Clear();
			FieldGuards.Clear();
			CompoundGuards.Clear();
		}

