		public static bool CanCameraPropSeePlayer(Prop Camera, float Angle, float Range)
		{
			bool flag = false;
			float heading = Camera.Heading;
			float num = 360f;
			float num2 = (Game.Player.Character.Position - Camera.Position).ToHeading();
			float num3 = 0f;
			int num4 = (int)num2;
			if (num4 >= 179)
			{
				num3 = (float)num4 - heading - 180f;
				if (num3 < -300f)
				{
					num3 += 360f;
				}
			}
			else
			{
				num3 = (float)num4 - heading + 180f;
				if (num3 > 300f)
				{
					num3 -= 360f;
				}
			}
			if (num3 >= 0f - Angle && num3 <= Angle)
			{
				RaycastResult raycastResult = World.Raycast(Camera.Position, Game.Player.Character.Position, IntersectFlags.Everything);
				flag = true;
				flag = raycastResult.DidHit && (GetDistance_VDIST2(Game.Player.Character.Position, raycastResult.HitPosition, "<", 2f) ? true : false);
			}
			else
			{
				flag = false;
			}
			if (GetDistance_VDIST2(Game.Player.Character.Position, Camera.Position, ">=", Range * 1f))
			{
				flag = false;
			}
			return flag;
		}

		public static void UpdateBlipConeData(Blip B, float Angle, float Range, bool ReverseBlipDirection)
		{
			Function.Call(Hash.REMOVE_FAKE_CONE_DATA, B);
			if (!ReverseBlipDirection)
			{
				Function.Call(Hash.SETUP_FAKE_CONE_DATA, B, -1f, 1f, Angle, 1f, Range, (float)(B.Rotation + 180) * (MathF.PI / 180f), 1, 11);
			}
			else
			{
				Function.Call(Hash.SETUP_FAKE_CONE_DATA, B, -1f, 1f, Angle, 1f, Range, (float)B.Rotation * (MathF.PI / 180f), 1, 11);
			}
			Function.Call(Hash.SET_BLIP_SHOW_CONE, B, true);
		}

