		public static void DeleteSetupMission5Assets()
		{
			foreach (ObjectPlacementMap item in SafehouseInterior)
			{
				if (item.Entity != null)
				{
					item.Entity.Delete();
				}
			}
			foreach (ObjectPlacementMap item2 in GangHideout)
			{
				if (item2.Entity != null)
				{
					item2.Entity.Delete();
				}
			}
			foreach (ObjectPlacementMap item3 in GasCutterLocation)
			{
				if (item3.Entity != null)
				{
					item3.Entity.Delete();
				}
			}
			ToolBoxes.Clear();
			ToolBoxesProps.Clear();
			if (Missionblip != null)
			{
				Missionblip.Delete();
			}
			if (Missionblip2 != null)
			{
				Missionblip2.Delete();
			}
		}

		public static void StartSetupMission5(GlobalOverrideMission OverrideMission = GlobalOverrideMission.None)
		{
			if (GlobalOverrideMissionID != GlobalOverrideMission.PlasmaCutter)
			{
				Notification.Show(HeistLeadername + " : if we are going to use the underwater enterance, we will need a Cutting tool to get though the bars, there might be one at a nearby construction site.");
			}
			else
			{
				Notification.Show(HeistLeadername + " : The display case in Mr. El Rubio's Vault is a problem, if we are going to get through it, we will need a Plasma Cutter, luckily a local gang has one for a robbery their planning. ");
			}
			SetupMission5GotPlasmaCutter = false;
			SetupMission5GotGasCutter = false;
			HeistStage = 5;
			DeleteSetupMission5Assets();
			if (GlobalOverrideMissionID == GlobalOverrideMission.CuttingTorch)
			{
				foreach (ObjectPlacementMap item in GasCutterLocation)
				{
					item.CreateObjatCoords();
				}
				int num = Function.Call<int>(Hash.GET_RANDOM_INT_IN_RANGE, 0, 500);
				if (num < 100)
				{
					Setup5GasCutter = (Prop)GasCutterLocation[0].Entity;
					GasCutterLocation[1].Entity.IsVisible = false;
					GasCutterLocation[2].Entity.IsVisible = false;
					GasCutterLocation[3].Entity.IsVisible = false;
					GasCutterLocation[4].Entity.IsVisible = false;
				}
				if (num >= 100 && num < 200)
				{
					Setup5GasCutter = (Prop)GasCutterLocation[1].Entity;
					GasCutterLocation[0].Entity.IsVisible = false;
					GasCutterLocation[2].Entity.IsVisible = false;
					GasCutterLocation[3].Entity.IsVisible = false;
					GasCutterLocation[4].Entity.IsVisible = false;
				}
				if (num >= 200 && num < 300)
				{
					Setup5GasCutter = (Prop)GasCutterLocation[2].Entity;
					GasCutterLocation[0].Entity.IsVisible = false;
					GasCutterLocation[1].Entity.IsVisible = false;
					GasCutterLocation[3].Entity.IsVisible = false;
					GasCutterLocation[4].Entity.IsVisible = false;
				}
				if (num >= 300 && num < 400)
				{
					Setup5GasCutter = (Prop)GasCutterLocation[3].Entity;
					GasCutterLocation[0].Entity.IsVisible = false;
					GasCutterLocation[1].Entity.IsVisible = false;
					GasCutterLocation[2].Entity.IsVisible = false;
					GasCutterLocation[4].Entity.IsVisible = false;
				}
				if (num >= 400 && num < 500)
				{
					Setup5GasCutter = (Prop)GasCutterLocation[4].Entity;
					GasCutterLocation[0].Entity.IsVisible = false;
					GasCutterLocation[1].Entity.IsVisible = false;
					GasCutterLocation[2].Entity.IsVisible = false;
					GasCutterLocation[3].Entity.IsVisible = false;
				}
				Prop b = (Prop)GasCutterLocation[5].Entity;
				ToolBoxes.Add(new ToolBox(b, false));
				b = (Prop)GasCutterLocation[6].Entity;
				ToolBoxes.Add(new ToolBox(b, false));
				b = (Prop)GasCutterLocation[7].Entity;
				ToolBoxes.Add(new ToolBox(b, false));
				b = (Prop)GasCutterLocation[8].Entity;
				ToolBoxes.Add(new ToolBox(b, false));
				b = (Prop)GasCutterLocation[9].Entity;
				ToolBoxes.Add(new ToolBox(b, false));
				b = (Prop)GasCutterLocation[10].Entity;
				ToolBoxes.Add(new ToolBox(b, false));
				SetupMission5Stage = 0;
				foreach (ObjectPlacementMap item2 in GasCutterLocation)
				{
					if (item2.Entity != null)
					{
						if (item2.Entity.Model.IsVehicle)
						{
							item2.Entity.IsInvincible = false;
						}
						if (item2.Entity.Model.IsPed)
						{
							item2.Entity.IsInvincible = false;
							item2.Entity.IsPositionFrozen = false;
							Ped ped = (Ped)item2.Entity;
							ped.Health = 300;
							ped.Weapons.Give(WeaponHash.CarbineRifle, 9999, true, true);
							SmartGuards.GuardGroup[23].GroupList.Add(new SmartGuards.SmartAiV2((Ped)item2.Entity, SmartGuards.EnemyGroup.Armenian_Mob));
						}
					}
				}
			}
			HeistStage = 5;
			SmartGuards.CurrentActiveGroup = SmartGuards.EnemyGroup.Armenian_Mob;
			if (Missionblip != null)
			{
				Missionblip.Delete();
			}
			if (Missionblip2 != null)
			{
				Missionblip2.Delete();
			}
			if (GlobalOverrideMissionID == GlobalOverrideMission.CuttingTorch)
			{
				Missionblip = World.CreateBlip(new Vector3(-907.14f, 151.15f, 70f));
				Missionblip.Sprite = BlipSprite.Standard;
				Missionblip.Color = BlipColor.Yellow;
				Missionblip.Name = "Construction Site";
				Missionblip2 = World.CreateBlip(new Vector3(-907.14f, 151.15f, 70f), 100f);
				Missionblip2.Color = BlipColor.Yellow;
				Missionblip2.Name = "Construction Site";
				Missionblip2.Alpha = 144;
			}
			else
			{
				Missionblip = World.CreateBlip(SafehouseEnterPos);
				Missionblip.Sprite = BlipSprite.Standard;
				Missionblip.Color = BlipColor.Yellow;
				Missionblip.Name = "Safehouse";
				Missionblip2 = World.CreateBlip(SafehouseEnterPos, 100f);
				Missionblip2.Color = BlipColor.Yellow;
				Missionblip2.Name = "Safehouse";
				Missionblip2.Alpha = 144;
				SetupMission5Stage = 1;
			}
			MissionOn = true;
		}

