		public static bool AllBarsDone()
		{
			bool result = true;
			for (int i = 0; i < Bars.Count; i++)
			{
				if (!Bars[i].IsCut)
				{
					result = false;
				}
			}
			return result;
		}

		public static void ResetBars()
		{
			foreach (GrateBar bar in Bars)
			{
				bar.IsCut = false;
			}
		}

