		public static void StartHangarDoorsOpenScene()
		{
			GTA.UI.Screen.FadeOut(1500);
			Script.Wait(1000);
			if (CinematicCam != null)
			{
				Function.Call(Hash.RENDER_SCRIPT_CAMS, 0, 0, 3000, 1, 0);
				CinematicCam.IsActive = false;
				CinematicCam.Delete();
			}
			CinematicCam = World.CreateCamera(new Vector3(-1153.66f, -3413.71f, 14.27f), new Vector3(0f, 0f, -29.73f), GameplayCamera.FieldOfView);
			CinematicCam.IsActive = true;
			CinematicCam.FarClip = 2000f;
			Function.Call(Hash.RENDER_SCRIPT_CAMS, 1, 0, 3000, 1, 0);
			Audio.SetAudioFlag(AudioFlags.LoadMPData, true);
			Audio.PlaySoundFrontend("hangar_doors_open", "dlc_xm_facility_entry_exit_sounds");
			Audio.SetAudioFlag(AudioFlags.LoadMPData, false);
			HangarDoorL = Function.Call<Prop>(Hash.GET_CLOSEST_OBJECT_OF_TYPE, -1152.779f, -3412.23f, 12.9f, 5f, Function.Call<int>(Hash.GET_HASH_KEY, "sf_prop_sf_door_hangar_01a"), 0, 0, 0);
			if (HangarDoorL != null)
			{
				HangarDoorL.Opacity = 255;
				if (HangarDoorL.IsAttached())
				{
					HangarDoorL.Detach();
				}
			}
			HangarDoorR = Function.Call<Prop>(Hash.GET_CLOSEST_OBJECT_OF_TYPE, -1152.6f, -3411.74f, 12.9f, 5f, Function.Call<int>(Hash.GET_HASH_KEY, "sf_prop_sf_door_hangar_01a"), 0, 0, 0);
			if (HangarDoorR != null)
			{
				HangarDoorR.Opacity = 255;
				if (HangarDoorR.IsAttached())
				{
					HangarDoorR.Detach();
				}
			}
			HangarDoorsTimeout = Game.GameTime + 5000;
			OpeningHangarDoors = true;
			Script.Wait(1000);
			GTA.UI.Screen.FadeIn(1500);
		}

