		public static RegionIn GetRegion(int ID)
		{
			RegionIn result = RegionIn.None;
			switch (ID)
			{
			case 0:
				result = RegionIn.Airfield;
				return RegionIn.Airfield;
			case 1:
				result = RegionIn.NorthDock;
				return RegionIn.NorthDock;
			case 2:
				result = RegionIn.Party;
				return RegionIn.Party;
			case 3:
				result = RegionIn.Checkpoint;
				return RegionIn.Checkpoint;
			case 4:
				result = RegionIn.SouthDock;
				return RegionIn.SouthDock;
			case 5:
				result = RegionIn.Fields;
				return RegionIn.Fields;
			case 6:
				result = RegionIn.CompoundExterior;
				return RegionIn.CompoundInterior;
			case 7:
				result = RegionIn.CompoundInterior;
				return RegionIn.CompoundInterior;
			default:
				return result;
			}
		}

