		public void GetPlayerRegion()
		{
			PlayerCurrentRegion = RegionIn.None;
			if (Zones[0].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[0].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.Airfield;
			}
			if (Zones[1].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[1].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.NorthDock;
			}
			if (Zones[2].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[2].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.Party;
			}
			if (Zones[3].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[3].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.Checkpoint;
			}
			if (Zones[4].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[4].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.SouthDock;
			}
			if (Zones[5].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[5].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.Fields;
			}
			if (Zones[6].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[6].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.CompoundExterior;
			}
			if (Zones[7].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Inside || Zones[7].Zone.WithBoundary(Game.Player.Character.Position) == PolygonFence.PointContainment.Coincident)
			{
				PlayerCurrentRegion = RegionIn.CompoundInterior;
			}
		}

		public static RegionIn GetRegionAtCoords(Vector3 X)
		{
			RegionIn result = RegionIn.None;
			if (Zones[0].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[0].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.Airfield;
			}
			if (Zones[1].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[1].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.NorthDock;
			}
			if (Zones[2].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[2].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.Party;
			}
			if (Zones[3].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[3].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.Checkpoint;
			}
			if (Zones[4].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[4].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.SouthDock;
			}
			if (Zones[5].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[5].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.Fields;
			}
			if (Zones[6].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[6].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.CompoundInterior;
			}
			if (Zones[6].Zone.WithBoundary(X) == PolygonFence.PointContainment.Inside || Zones[6].Zone.WithBoundary(X) == PolygonFence.PointContainment.Coincident)
			{
				return RegionIn.CompoundExterior;
			}
			return result;
		}

		public static void SetScubaGear()
		{
			if (!(Game.Player.Character.LastVehicle != null) || !Game.Player.Character.LastVehicle.Model.IsBoat)
			{
				return;
			}
			if (Game.Player.Character.IsInWater || Game.Player.Character.IsDiving)
			{
				if (Game.Player.Character.IsSwimming)
				{
					Function.Call(Hash.SET_PED_SCUBA_GEAR_VARIATION, Game.Player.Character);
					Function.Call(Hash.ENABLE_MP_LIGHT, Game.Player.Character, true);
				}
			}
			else
			{
				Function.Call(Hash.ENABLE_MP_LIGHT, Game.Player.Character, false);
			}
		}

