		public static void GetGuardSettings()
		{
			InSafezone1 = Function.Call<bool>(Hash.IS_ENTITY_IN_AREA, Game.Player.Character, 3851.5f, -4690.212f, -1.666132f, 4583.16f, -4460.18f, 37.89993f, 1, 1, 0);
			if (!InSafezone1 && GetDistance_VDIST2(Game.Player.Character.Position, new Vector3(4481.96f, -4450.16f, 3.05f), "<", 100f))
			{
				InSafezone1 = true;
			}
			InCompound = PlayerCurrentRegion == RegionIn.CompoundInterior;
			InSafezone2 = GetDistance_VDIST2(Game.Player.Character.Position, new Vector3(4900.152f, -4909.51f, 2.6f), "<", 100f);
			if (GuardsAlerted)
			{
				if (HeistStage != 7)
				{
					SmartAISettings_Guards.Radius = 125f;
					SmartAISettings_Guards.ShowBlipRadius = 250f;
					SmartAISettings_Guards.HitRadius = 3.25f;
					SmartAISettings_Guards.AllowInvestigate = true;
					SmartAISettings_Guards.InvestigateDist = 40f;
					SmartAISettings_Guards.SeeingAngle = 30f;
					SmartAISettings_Guards.RunPatrolRoute = false;
					SmartAISettings_Guards.ArrestInsteadOfShoot = false;
				}
			}
			else if (InCompound)
			{
				SmartAISettings_Guards.HearingRange = 3.5f;
				SmartAISettings_Guards.Radius = 35f;
				SmartAISettings_Guards.ShowBlipRadius = 250f;
				SmartAISettings_Guards.HitRadius = 3.25f;
				SmartAISettings_Guards.AllowInvestigate = false;
				SmartAISettings_Guards.InvestigateDist = 20f;
				SmartAISettings_Guards.SeeingAngle = 25f;
				SmartAISettings_Guards.RunPatrolRoute = false;
				SmartAISettings_Guards.ArrestInsteadOfShoot = false;
			}
			else
			{
				SmartAISettings_Guards.HearingRange = 12.5f;
				SmartAISettings_Guards.Radius = 90f;
				SmartAISettings_Guards.ShowBlipRadius = 250f;
				SmartAISettings_Guards.HitRadius = 3.25f;
				SmartAISettings_Guards.AllowInvestigate = true;
				SmartAISettings_Guards.InvestigateDist = 40f;
				SmartAISettings_Guards.SeeingAngle = 30f;
				SmartAISettings_Guards.RunPatrolRoute = false;
				SmartAISettings_Guards.ArrestInsteadOfShoot = false;
			}
			SmartAISettings_Guards.ShowCone = true;
			MatchSettings();
			if (InSafezone1 || InSafezone2)
			{
				if (!SmartAISettings_Guards.HasTargettedAI)
				{
					SmartAISettings_Guards.IngorePlayer = true;
				}
				else
				{
					SmartAISettings_Guards.IngorePlayer = false;
					SmartAISettings_Guards.ArrestInsteadOfShoot = false;
				}
			}
			else
			{
				SmartAISettings_Guards.IngorePlayer = false;
				SmartAISettings_Guards.ArrestInsteadOfShoot = false;
			}
			if ((!MissionOn || HeistStage == 1) && !SmartAISettings_Guards.HasTargettedAI)
			{
				SmartAISettings_Guards.ArrestInsteadOfShoot = true;
			}
			if (HeistStage == 1 && MissionStage < 4)
			{
				SmartAISettings_Guards.IngorePlayer = true;
			}
		}

		public void ShowZones()
		{
			Point p = new Point((int)Game.Player.Character.Position.X, (int)Game.Player.Character.Position.Y);
			float num = 0.03f;
			if (Zones.Count < 0)
			{
				return;
			}
			for (int i = 0; i < Zones.Count; i++)
			{
				if (i == 3)
				{
					num = 0.03f;
				}
				drawText("Is In Zone " + i + ": " + Zones[i].Zone.IsWithinFence(p), 0.5f, 0.1f + num, 0.3f, 255, 255, 255);
				num += 0.03f;
				num += 0.05f;
				for (int j = 0; j < 60; j++)
				{
					for (int k = 1; k < Zones[i].Zone.PointList.Count; k++)
					{
						DrawLine(new Vector3(Zones[i].Zone.PointList[k].X, Zones[i].Zone.PointList[k].Y, 1.5f + 1.5f * (float)j), new Vector3(Zones[i].Zone.PointList[k - 1].X, Zones[i].Zone.PointList[k - 1].Y, 1.5f + 1.5f * (float)j), new Vector3(0f, 255f, 255f));
						World.DrawMarker(MarkerType.Cylinder, new Vector3(Zones[i].Zone.PointList[k].X, Zones[i].Zone.PointList[k].Y, 0f), Vector3.Zero, Vector3.Zero, new Vector3(1f, 1f, 100f), Color.FromArgb(0, 255, 255));
					}
				}
			}
		}

