		public void DriveToPartyAnim()
		{
			if (Game.IsControlPressed(Control.Sprint) && Game.IsControlJustPressed(Control.VehicleDuck))
			{
				Vehicle vehicle = World.CreateVehicle(RequestModel("WINKY"), Game.Player.Character.Position.Around(5f), -115f);
				vehicle.IsInvincible = true;
				Vehicles.Add(vehicle);
				Ped ped = World.CreatePed(RequestModel("ig_juanstrickler"), default(Vector3));
				ped.SetIntoVehicle(vehicle, VehicleSeat.Passenger);
				ped.BlockPermanentEvents = true;
				ped.RelationshipGroup = 2;
				Peds.Add(ped);
				ElRubio = ped;
