				Function.Call(Hash.SET_PED_AMMO, Game.Player.Character, WeaponHash.AssaultrifleMk2, 9999, true);
			}
			if (Game.Player.Character.Weapons.HasWeapon(WeaponHash.PistolMk2))
			{
				Function.Call(Hash.GIVE_WEAPON_COMPONENT_TO_PED, Game.Player.Character, WeaponHash.PistolMk2, WeaponComponentHash.AtPiFlsh02);
				Function.Call(Hash.GIVE_WEAPON_COMPONENT_TO_PED, Game.Player.Character, WeaponHash.PistolMk2, WeaponComponentHash.PistolMk2ClipFMJ);
				if (UseSuppressors)
				{
					Function.Call(Hash.GIVE_WEAPON_COMPONENT_TO_PED, Game.Player.Character, WeaponHash.PistolMk2, WeaponComponentHash.AtPiSupp02);
				}
				Function.Call(Hash.SET_PED_AMMO, Game.Player.Character, WeaponHash.PistolMk2, 9999, true);
			}
			else
			{
				Game.Player.Character.Weapons.Give(WeaponHash.PistolMk2, 9999, true, true);
				Function.Call(Hash.GIVE_WEAPON_COMPONENT_TO_PED, Game.Player.Character, WeaponHash.PistolMk2, WeaponComponentHash.AtPiFlsh02);
				Function.Call(Hash.GIVE_WEAPON_COMPONENT_TO_PED, Game.Player.Character, WeaponHash.PistolMk2, WeaponComponentHash.PistolMk2ClipFMJ);
				if (UseSuppressors)
				{
					Function.Call(Hash.GIVE_WEAPON_COMPONENT_TO_PED, Game.Player.Character, WeaponHash.PistolMk2, WeaponComponentHash.AtPiSupp02);
				}
				Function.Call(Hash.SET_PED_AMMO, Game.Player.Character, WeaponHash.PistolMk2, 9999, true);
			}
			if (!Game.Player.Character.Weapons.HasWeapon(WeaponHash.Machete))
			{
				Game.Player.Character.Weapons.Give(WeaponHash.Machete, 9999, true, true);
			}
			if (!Game.Player.Character.Weapons.HasWeapon(WeaponHash.PipeBomb))
			{
				Game.Player.Character.Weapons.Give(WeaponHash.PipeBomb, 5, true, true);
			}
			Function.Call(Hash.SET_PED_AMMO, Game.Player.Character, WeaponHash.PipeBomb, 5, true);
		}

		public static void HandleWeaponLoadout()
		{
			WeaponHash item = (WeaponHash)Function.Call<uint>(Hash.GET_SELECTED_PED_WEAPON, Game.Player.Character);
			if (Game.IsControlPressed(Control.SelectWeapon))
			{
				if (!Loadout_Current.Contains(item))
				{
					DisplayingCantChooseWeaponDialogue = true;
					DisplayHelpTextThisFrame("During the Cayo Perico Heist, Player's Loadout is Limited to certain weapons, selecting this weapon is unavailable at this time.", 1);
				}
			}
			else
			{
				DisplayingCantChooseWeaponDialogue = false;
			}
		}

		public static void DrawLives(string Detail, int Number)
		{
			UI.drawSprite2("timerbars", "all_black_bg", 0.89f, 0.97f - UI.RenderQue, 0.21f, 0.04f);
			UI.drawText(Detail, UI.DrawText_XCoord, 0.961f - UI.RenderQue, 0.3f, 255, 255, 255);
			UI.drawNumber(Number, 0.92f, 0.952f - UI.RenderQue, 0.48f, 255, 255, 255, false);
			UI.RenderQue += UI.RenderQueRemove;
		}

		public static void ManageLives()
		{
			if (!Game.Player.Character.IsAlive)
			{
				if (!JustDied)
				{
					InvincibleTime = Game.GameTime + 5000;
					Lives--;
					JustDied = true;
					RespawnMovePosTimer = -1;
				}
			}
			else
			{
				if (JustDied)
				{
					if (RespawnMovePosTimer == -1)
					{
						RespawnMovePosTimer = Game.GameTime + 1000;
					}
					else if (Game.GameTime > RespawnMovePosTimer)
					{
						RespawnMovePosTimer = -1;
						Game.Player.Character.Health = Game.Player.Character.MaxHealth;
						Game.Player.Character.Armor = Game.Player.MaxArmor;
						foreach (SmartGuards.EnemyGroupData item in SmartGuards.GuardGroup)
						{
							item.Settings.AI_Target = Game.Player.Character;
						}
						JustDied = false;
					}
				}
				if (InvincibleTime != -1)
				{
					if (Game.GameTime < InvincibleTime)
					{
						Game.Player.Character.IsInvincible = true;
					}
					if (Game.GameTime >= InvincibleTime)
					{
						InvincibleTime = -1;
					}
				}
			}
			DrawLives("LIVES: ", Lives);
		}

		public static void ToggleAllWeapons(bool TF)
		{
			SetLoadout();
			if (TF)
			{
				Function.Call(Hash.SET_USE_ISLAND_MAP, false);
			}
			if (!TF)
			{
				Function.Call(Hash.SET_USE_ISLAND_MAP, true);
				Class1.ExpandedWeaponHash[] array = (Class1.ExpandedWeaponHash[])Enum.GetValues(typeof(Class1.ExpandedWeaponHash));
				foreach (Class1.ExpandedWeaponHash expandedWeaponHash in array)
				{
					uint num = (uint)expandedWeaponHash;
					Function.Call(Hash.SET_CAN_PED_SELECT_INVENTORY_WEAPON, Game.Player.Character, num, false);
				}
				WeaponHash[] array2 = (WeaponHash[])Enum.GetValues(typeof(WeaponHash));
				foreach (WeaponHash weaponHash in array2)
				{
					uint num2 = (uint)weaponHash;
					Function.Call(Hash.SET_CAN_PED_SELECT_INVENTORY_WEAPON, Game.Player.Character, num2, false);
				}
				{
					foreach (WeaponHash item in Loadout_Current)
					{
						if (Loadout_Current.Contains(item))
						{
							Function.Call(Hash.HUD_SET_WEAPON_WHEEL_TOP_SLOT, item);
						}
						uint num3 = (uint)item;
						Function.Call(Hash.SET_CAN_PED_SELECT_INVENTORY_WEAPON, Game.Player.Character, num3, true);
					}
					return;
				}
			}
			Class1.ExpandedWeaponHash[] array3 = (Class1.ExpandedWeaponHash[])Enum.GetValues(typeof(Class1.ExpandedWeaponHash));
			foreach (Class1.ExpandedWeaponHash expandedWeaponHash2 in array3)
			{
				uint num4 = (uint)expandedWeaponHash2;
				Function.Call(Hash.SET_CAN_PED_SELECT_INVENTORY_WEAPON, Game.Player.Character, num4, true);
			}
		}

		private void CreateOText(int office)
		{
			switch (OStage)
			{
			case 0:
				DeleteOText();
				OSMovie = Function.Call<int>(Hash.REQUEST_SCALEFORM_MOVIE, "ORGANISATION_NAME");
				if (!Function.Call<bool>(Hash.IS_NAMED_RENDERTARGET_REGISTERED, "prop_ex_office_text"))
				{
					Function.Call(Hash.REGISTER_NAMED_RENDERTARGET, "prop_ex_office_text", 0);
				}
				if (!Function.Call<bool>(Hash.IS_NAMED_RENDERTARGET_LINKED, -2082168399))
				{
					Function.Call(Hash.LINK_NAMED_RENDERTARGET, -2082168399);
				}
				OSF1 = Function.Call<int>(Hash.GET_NAMED_RENDERTARGET_RENDER_ID, "prop_ex_office_text");
				OStage = 1;
				break;
			case 1:
				if (Function.Call<bool>(Hash.HAS_SCALEFORM_MOVIE_LOADED, OSMovie))
				{
					Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, OSMovie, "SET_ORGANISATION_NAME");
					if (office == 1)
					{
						officetext = CurrentText;
						ao = currentColor;
						bo = currentFont;
					}
					if (office == 2)
					{
						officetext = CurrentText;
						ao = currentColor;
						bo = currentFont;
					}
					if (office == 3)
					{
						officetext = CurrentText;
						ao = currentColor;
						bo = currentFont;
					}
					if (office == 4)
					{
						officetext = CurrentText;
						ao = currentColor;
						bo = currentFont;
					}
					Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_LITERAL_STRING, officetext);
					Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_INT, 0);
					Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_INT, ao);
					Function.Call(Hash.SCALEFORM_MOVIE_METHOD_ADD_PARAM_INT, bo);
					Function.Call(Hash.END_SCALEFORM_MOVIE_METHOD);
					Function.Call(Hash.SET_SCALEFORM_MOVIE_TO_USE_LARGE_RT, OSMovie, 1);
					OStage = 2;
				}
				else
				{
					OSMovie = Function.Call<int>(Hash.REQUEST_SCALEFORM_MOVIE, "ORGANISATION_NAME");
				}
				break;
			case 2:
				Function.Call(Hash.SET_TEXT_RENDER_ID, OSF1);
				Function.Call(Hash.SET_SCRIPT_GFX_DRAW_ORDER, 4);
				Function.Call(Hash.SET_SCRIPT_GFX_DRAW_BEHIND_PAUSEMENU, 1);
				Function.Call(Hash.SET_SCRIPT_GFX_ALIGN, 73, 73);
				Function.Call(Hash.DRAW_SCALEFORM_MOVIE, OSMovie, 0.196f, 0.245f, 0.46f, 0.66f, 255, 255, 255, 255, 0);
				Function.Call(Hash.SET_TEXT_RENDER_ID, Function.Call<int>(Hash.GET_DEFAULT_SCRIPT_RENDERTARGET_RENDER_ID));
				break;
			}
		}

		private void DeleteOText()
		{
			if (Function.Call<bool>(Hash.IS_NAMED_RENDERTARGET_REGISTERED, "prop_ex_office_text"))
			{
				Function.Call(Hash.RELEASE_NAMED_RENDERTARGET, "prop_ex_office_text");
			}
			OStage = 0;
		}

