		public static void StartCayoPericoHeistFinale()
		{
			MissionOn = false;
			CayoPericoMissionSetup = GlobalOverrideMission.None;
			CameraON = false;
			UI.HeistFrontend.ExitedFrontEndHeistMenu = false;
			if (!FinaleLocked)
			{
				HeistStage = 7;
				Config.SetValue("CAYOPERICOHEIST", "HEISTSTAGE", 7);
				Config.Save();
			}
			ToggleAllWeapons(false);
			ManageRobberyAnims.DeleteLoot();
			SpawnedKosatkaBoat = false;
			if (MainBoat != null)
			{
				MainBoat.Delete();
			}
			GotGrappleHook = false;
			CamerasDestoryed = 0;
			MaxCamerasDestroyed = 6;
			foreach (ObjectPlacementMap exitKosatkaPosition in ExitKosatkaPositions)
			{
				if (exitKosatkaPosition.Entity != null)
				{
					exitKosatkaPosition.Entity.Delete();
				}
			}
			foreach (ObjectPlacementMap finaleSamSite in FinaleSamSites)
			{
				if (finaleSamSite.Entity != null)
				{
					finaleSamSite.Entity.Delete();
				}
			}
			foreach (ObjectPlacementMap item in PowerStationAndControllTower)
			{
				if (item.Entity != null)
				{
					item.Entity.Delete();
				}
			}
			foreach (ObjectPlacementMap underwaterGrateObject in UnderwaterGrateObjects)
			{
				if (underwaterGrateObject.Entity != null)
				{
					underwaterGrateObject.Entity.Delete();
				}
			}
			foreach (ObjectPlacementMap setup1Extra in Setup1Extras)
			{
				if (setup1Extra.Entity != null)
				{
					setup1Extra.Entity.Delete();
				}
			}
			foreach (Ped merryweatherPed in MerryweatherPeds)
			{
				if (merryweatherPed != null)
				{
					merryweatherPed.Delete();
				}
			}
			MerryweatherPeds.Clear();
			foreach (Vehicle merryweatherVehicle in MerryweatherVehicles)
			{
				if (merryweatherVehicle != null)
				{
					merryweatherVehicle.Delete();
				}
			}
			MerryweatherVehicles.Clear();
			GuardsAlerted = false;
			ShutDownCCTV = false;
			ShutDownAirDefences = false;
			PowerStationBoxAOff = false;
			PowerStationBoxBOff = false;
			VTMinigameOn = false;
			HackedAirDefenceStation = false;
			SetupSetup1Extras();
			SetupFinaleExtras();
			PlayingUnderwaterEnterCutscene = false;
			RequestedUnderwaterEnterCompoundScene = false;
			ManageCayoPericoDialogue.ResetAllAudioVars();
			ManageRobberyAnims.Cannot_Steal_Loot = false;
			MissionStage = 0;
			SetupAi = true;
			Hackerskill = 5;
			foreach (CayoGate cayoPericoGate in CayoPericoGates)
			{
				cayoPericoGate.LGateOriginaHeading = -1f;
				cayoPericoGate.RGateOriginaHeading = -1f;
				if (cayoPericoGate.Chain != null)
				{
					cayoPericoGate.Chain.Delete();
				}
				cayoPericoGate.GateLocked = true;
			}
			CleanupGuards();
			SetupGuardLists();
			Function.Call(Hash.WATER_OVERRIDE_SET_STRENGTH, 0f);
			SetupCayoPericoGuardSpawns = true;
			Game.Player.SetControlState(true);
			modLemonUIObjectPool.HideAll();
			EndofHiest(false);
			Function.Call(Hash.ANIMPOSTFX_PLAY, "MP_job_load", 0, false);
			Function.Call(Hash.PLAY_SOUND_FRONTEND, -1, "CHECKPOINT_PERFECT", "HUD_MINI_GAME_SOUNDSET", false);
			Function.Call(Hash.TOGGLE_PAUSED_RENDERPHASES, false);
			Game.Player.SetControlState(true);
			Game.Player.Character.CanSwitchWeapons = true;
			Game.Player.Character.Task.ClearAllImmediately();
			Script.Wait(500);
			Audio.SetAudioFlag(AudioFlags.LoadMPData, true);
			Audio.SetAudioFlag(AudioFlags.WantedMusicDisabled, true);
			Audio.SetAudioFlag(AudioFlags.DisableFlightMusic, true);
			Script.Wait(1000);
			Function.Call(Hash.ANIMPOSTFX_STOP, "MP_job_load", 0, false);
			LoadingPrompt.Hide();
			Function.Call(Hash.TOGGLE_PAUSED_RENDERPHASES, true);
			GTA.UI.Screen.ClearHelpText();
			if (Function.Call<bool>(Hash.IS_HUD_HIDDEN))
			{
				Function.Call(Hash.DISPLAY_HUD, true);
			}
			if (Function.Call<bool>(Hash.IS_RADAR_HIDDEN))
			{
				Function.Call(Hash.DISPLAY_RADAR, true);
			}
			Function.Call(Hash.CLEAR_TIMECYCLE_MODIFIER);
			Function.Call(Hash.ANIMPOSTFX_STOP_ALL);
			if (!Function.Call<bool>(Hash.GET_TOGGLE_PAUSED_RENDERPHASES_STATUS))
			{
				Function.Call(Hash.TOGGLE_PAUSED_RENDERPHASES, true);
			}
			Function.Call(Hash.TRIGGER_MUSIC_EVENT, "GTA_ONLINE_STOP_SCORE");
			SetupAi = false;
			GotMadrazzoSafe = false;
			Lives = 3;
			Function.Call(Hash.CLEAR_TIMECYCLE_MODIFIER);
			Function.Call(Hash.POP_TIMECYCLE_MODIFIER);
			Function.Call(Hash.SET_TIMECYCLE_MODIFIER, "default");
			if (Function.Call<int>(Hash.GET_TIMECYCLE_MODIFIER_INDEX) != -1)
			{
				Function.Call(Hash.CLEAR_TIMECYCLE_MODIFIER);
			}
			Function.Call(Hash.DISPLAY_HUD, true);
			Function.Call(Hash.DISPLAY_RADAR, true);
			Game.Player.SetControlState(true);
			Game.Player.Character.CanSwitchWeapons = true;
