		public unsafe static void ManageOpenWallSafe()
		{
			if (!OpenedMadrazoWallSafe)
			{
				Prop prop = Function.Call<Prop>(Hash.GET_CLOSEST_OBJECT_OF_TYPE, 5010.795f, -5759.236f, 28.89504f, 5f, Function.Call<int>(Hash.GET_HASH_KEY, "h4_prop_door_safe_01"), 0, 0, 0);
				if (!(prop != null))
				{
					return;
				}
				if (!IsOpeningWallSafe)
				{
					if (!GetDistance_VDIST2(Game.Player.Character.Position, new Vector3(5010.795f, -5759.236f, 28.89504f), "<", 2f))
					{
						return;
					}
					DisplayHelpTextThisFrame("Press ~INPUT_AIM~ to open wall safe.");
					if (!Game.IsControlJustPressed(Control.Aim))
					{
						return;
					}
					GotWallSafeCashStack = false;
					Script.Wait(100);
					string text = "anim@amb@office@boss@vault@left@male@";
					LoadDict("anim@amb@office@boss@vault@left@male@");
					if (Function.Call<bool>(Hash.HAS_ANIM_DICT_LOADED, text))
					{
						Vector3 vector = new Vector3(5010.795f, -5759.236f, 28.89504f);
						float num = -31.82f;
						Vector3 vector2 = Function.Call<Vector3>(Hash.GET_ANIM_INITIAL_OFFSET_POSITION, LoadDict(text), "open", vector.X, vector.Y, vector.Z, 0, 0, num, 0f, 2);
						Vector3 vector3 = Function.Call<Vector3>(Hash.GET_ANIM_INITIAL_OFFSET_ROTATION, LoadDict(text), "open", vector.X, vector.Y, vector.Z, 0, 0, num, 0f, 2);
						int num2 = 0;
						Function.Call(Hash.OPEN_SEQUENCE_TASK, &num2);
						Function.Call(Hash.TASK_PED_SLIDE_TO_COORD, 0, vector2.X, vector2.Y, vector2.Z, vector3.Z, 8f);
						Function.Call(Hash.CLOSE_SEQUENCE_TASK, num2);
						Function.Call(Hash.TASK_PERFORM_SEQUENCE, Game.Player.Character, num2);
						Function.Call(Hash.CLEAR_SEQUENCE_TASK, &num2);
						Script.Wait(100);
						while (Function.Call<int>(Hash.GET_SEQUENCE_PROGRESS, Game.Player.Character) != -1)
						{
							Script.Wait(0);
						}
						prop.Rotation = new Vector3(0f, 0f, -31.82f);
						Prop gunlockerDoor = GunlockerDoor;
						OpenWallSafeScene = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE, prop.Position.X, prop.Position.Y, prop.Position.Z, 0.0, 0.0, prop.Rotation.Z, 2);
						Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, Game.Player.Character, OpenWallSafeScene, LoadDict("anim@amb@office@boss@vault@left@male@"), "open", 16f, -16f, 0, 1148846080);
						Function.Call(Hash.SET_SYNCHRONIZED_SCENE_PHASE, OpenWallSafeScene, Function.Call<int>(Hash.GET_SYNCHRONIZED_SCENE_PHASE, OpenWallSafeScene));
						Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, Game.Player.Character, OpenWallSafeScene, "open", LoadDict("anim@amb@office@boss@vault@left@male@"), 16f, -16f, 0, 1148846080);
						Function.Call(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, prop, OpenWallSafeScene, "open_door", LoadDict("anim@amb@office@boss@vault@left@male@"), 16f, -16f, 0, 1148846080);
						IsOpeningWallSafe = true;
						if (WallSafeCash != null)
						{
							WallSafeCash.Delete();
						}
						WallSafeCash = World.CreateProp(RequestModel("h4_prop_h4_cash_stack_02a"), new Vector3(5010.03027f, -5759.211f, 28.66f), new Vector3(0f, 0f, 148.14f), false, false);
					}
				}
				else if (Function.Call<int>(Hash.GET_SYNCHRONIZED_SCENE_PHASE, OpenWallSafeScene) >= 1065353216)
				{
					OpenedMadrazoWallSafe = true;
					IsOpeningWallSafe = false;
					Game.Player.Character.Task.ClearAllImmediately();
				}
			}
			else if (!GotWallSafeCashStack && WallSafeCash != null && GetDistance_VDIST2(Game.Player.Character.Position, WallSafeCash.Position, "<", 1.5f))
			{
				EntityFlickerEffect.VehicleFadeEffects.Add(new EntityFlickerEffect.FadeEffect(WallSafeCash, false));
				GotWallSafeCashStack = true;
				ManageRobberyAnims.CurrentPay += Function.Call<int>(Hash.GET_RANDOM_INT_IN_RANGE, 35000, 110000);
			}
		}

