		public static void SetupSetup1Extras()
		{
			foreach (ObjectPlacementMap setup1Extra in Setup1Extras)
			{
				setup1Extra.CreateObjatCoords();
			}
			NorthDockIndicator = (Prop)Setup1Extras[0].Entity;
			NorthDockIndicator.IsVisible = false;
			SouthDockIndicator = (Prop)Setup1Extras[1].Entity;
			SouthDockIndicator.IsVisible = false;
			ControlTowerPhotoTarget = (Prop)Setup1Extras[5].Entity;
			ControlTowerPhotoTarget.IsCollisionEnabled = false;
			ControlTowerPhotoTarget.IsVisible = false;
		}

		public static void SetupFinaleExtras()
		{
			foreach (ObjectPlacementMap finaleSamSite in FinaleSamSites)
			{
				finaleSamSite.CreateObjatCoords();
				Script.Wait(0);
				if (finaleSamSite.Entity != null)
				{
					finaleSamSite.Entity.IsInvincible = true;
					Samsites.Add(new SamSite((Prop)finaleSamSite.Entity));
				}
			}
			foreach (ObjectPlacementMap item in PowerStationAndControllTower)
			{
				item.CreateObjatCoords();
			}
			int num = Function.Call<int>(Hash.GET_RANDOM_INT_IN_RANGE, 0, 300);
			if (num <= 100)
			{
				ControlTowerElecBox = (Prop)PowerStationAndControllTower[0].Entity;
				PowerStationAndControllTower[1].Entity.IsVisible = false;
				PowerStationAndControllTower[2].Entity.IsVisible = false;
			}
			if (num > 100 && num <= 200)
			{
				ControlTowerElecBox = (Prop)PowerStationAndControllTower[1].Entity;
				PowerStationAndControllTower[0].Entity.IsVisible = false;
				PowerStationAndControllTower[2].Entity.IsVisible = false;
			}
			if (num > 200 && num <= 300)
			{
				ControlTowerElecBox = (Prop)PowerStationAndControllTower[2].Entity;
				PowerStationAndControllTower[0].Entity.IsVisible = false;
				PowerStationAndControllTower[1].Entity.IsVisible = false;
			}
			PowerstationControlA = (Prop)PowerStationAndControllTower[3].Entity;
			PowerstationControlB = (Prop)PowerStationAndControllTower[4].Entity;
			GotBoltCutters = true;
			foreach (ObjectPlacementMap underwaterGrateObject in UnderwaterGrateObjects)
			{
				underwaterGrateObject.CreateObjatCoords();
			}
			UnderwaterGrateObjects[1].Entity.AttachTo(UnderwaterGrateObjects[0].Entity, new Vector3(0f, 0f, 0f), new Vector3(0f, 0f, 0f));
		}

		public static bool HasVector3BeenPhotographed(Vector3 Pos, float Dist)
		{
			bool result = false;
			int num = Function.Call<int>(Hash.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, Function.Call<int>(Hash.GET_HASH_KEY, "appCamera"));
			if (num == 1)
			{
				CameraOpenTime++;
			}
			else
			{
				CameraOpenTime = 0;
			}
			bool flag = !Function.Call<bool>(Hash.PHONEPHOTOEDITOR_IS_ACTIVE) && num == 1 && CameraOpenTime >= 100;
			if (Game.IsControlJustPressed(Control.PhoneCancel))
			{
				CameraOpenTime = 0;
				num = 0;
				flag = false;
			}
			if (num == 0)
			{
				flag = false;
			}
			if (World.Raycast(Game.Player.Character.Position, Pos, IntersectFlags.Everything).DidHit)
			{
				flag = false;
			}
			Vector2 vector = World3DToScreen2d(Pos);
			if (vector.X == -1f || vector.Y == -1f)
			{
				flag = false;
			}
			if (!flag)
			{
				return false;
			}
			if (GetDistance_VDIST2(Game.Player.Character.Position, Pos, "<", Dist) && flag)
			{
				CameraOpenTime = 0;
				flag = false;
				if (num == 1)
				{
					AwaitPhoneClose = true;
				}
			}
			if (AwaitPhoneClose)
			{
				return true;
			}
			return result;
		}

		public static bool HasEntityBeenPhotographed(Entity entity, float Dist)
		{
			bool result = false;
			int num = Function.Call<int>(Hash.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, Function.Call<int>(Hash.GET_HASH_KEY, "appCamera"));
			if (num == 1)
			{
				CameraOpenTime++;
			}
			else
			{
				CameraOpenTime = 0;
			}
			bool flag = !Function.Call<bool>(Hash.PHONEPHOTOEDITOR_IS_ACTIVE) && num == 1 && CameraOpenTime >= 100;
			if (Game.IsControlJustPressed(Control.PhoneCancel))
			{
				CameraOpenTime = 0;
				num = 0;
				flag = false;
			}
			if (num == 0)
			{
				flag = false;
			}
			if (!entity.IsOnScreen)
			{
				flag = false;
			}
			if (!flag)
			{
				return false;
			}
			if (entity != null && GetDistance_VDIST2(Game.Player.Character.Position, entity.Position, "<", Dist))
			{
				GTA.UI.Screen.ShowSubtitle("ControlTowerPhotoTarget active");
				if (flag)
				{
					CameraOpenTime = 0;
					flag = false;
					if (num == 1)
					{
						AwaitPhoneClose = true;
					}
				}
			}
			if (AwaitPhoneClose)
			{
				return true;
			}
			return result;
		}

		public static void SetMainTargetString(int ID)
		{
			if (ID == 0)
			{
				CurrentMainTargetID = MainTargets.MadrazoFiles;
			}
			if (ID == 1)
			{
				CurrentMainTargetID = MainTargets.CashBonds;
			}
			if (ID == 2)
			{
				CurrentMainTargetID = MainTargets.SinsimitoTequila;
			}
			if (ID == 3)
			{
				CurrentMainTargetID = MainTargets.RubyNecklace;
			}
			if (ID == 4)
			{
				CurrentMainTargetID = MainTargets.PinkDiamond;
			}
			if (ID == 5)
			{
				CurrentMainTargetID = MainTargets.PantherStatue;
			}
			GetMainTargetString();
		}

		public static void GetMainTargetString()
		{
			if (CurrentMainTargetID == MainTargets.MadrazoFiles)
			{
				CurrentTarget = "Madrazo Files";
			}
			if (CurrentMainTargetID == MainTargets.CashBonds)
			{
				CurrentTarget = "Cash Bonds";
			}
			if (CurrentMainTargetID == MainTargets.SinsimitoTequila)
			{
				CurrentTarget = "Sinsimito Tequila";
			}
			if (CurrentMainTargetID == MainTargets.RubyNecklace)
			{
				CurrentTarget = "Ruby Necklace";
			}
			if (CurrentMainTargetID == MainTargets.PinkDiamond)
			{
				CurrentTarget = "Pink Diamond";
			}
			if (CurrentMainTargetID == MainTargets.PantherStatue)
			{
				CurrentTarget = "Panther Statue";
			}
		}

