			{
				num2 = 4;
				num = 1100000;
			}
			if (mainTargetID == 1)
			{
				num2 = 2;
				num = 1100000;
			}
			if (mainTargetID == 2)
			{
				num2 = 0;
				num = 630000;
			}
			if (mainTargetID == 3)
			{
				num2 = 1;
				num = 700000;
			}
			if (mainTargetID == 4)
			{
				num2 = 3;
				num = 1300000;
			}
			if (mainTargetID == 4)
			{
				num2 = 5;
				num = 1900000;
			}
			string title = "Cayo Perico Heist";
			string description = "A full-scale island raid on El Rubio’s private fortress. Infiltrate docks, airstrips, and underground vaults while navigating patrols, cameras, and armored guards. The island’s isolation makes escape difficult — every route is dangerous, and every second counts.";
			int num3 = num;
			GTA.UI.Screen.FadeOut(250);
			Script.Wait(2000);
			UI.InitializeFrontentHeistMenu(title, description, num3);
			Script.Wait(250);
			UI.FrontendLobbyMenu.Release();
			Script.Wait(1000);
			GTA.UI.Screen.FadeIn(250);
			Script.Wait(250);
			CameraON = true;
			Game.Player.Character.Position = StartHeistMarker;
			Game.Player.Character.Heading = 90f;
			Vector3 offsetPosition = Game.Player.Character.GetOffsetPosition(new Vector3(0f, 2.5f, 1f));
			Game.Player.Character.IsPositionFrozen = false;
			HeistStartCam = World.CreateCamera(offsetPosition, new Vector3(0f, 0f, 85f), 60f);
			HeistStartCam.IsActive = true;
			HeistStartCam.FarClip = 2000f;
			HeistStartCam.PointAt(Game.Player.Character);
			Function.Call(Hash.RENDER_SCRIPT_CAMS, 1, 0, 3000, 1, 0);
			Game.Player.Character.IsPositionFrozen = true;
			Game.Player.SetControlState(false);
